module fp_fabs(
input wire sysclk,
input wire reset,
input wire enable,
input wire signin,
input wire [8:1] exponentin,
input wire [23:1] mantissain,
output wire signout,
output wire [8:1] exponentout,
output wire [23:1] mantissaout,
output wire satout,
output wire zeroout,
output wire nanout
);
reg signff;
reg [8:1] exponentff;
reg [23:1] mantissaff;
wire [8:1] expnode;
wire [8:1] expzerochk; wire [8:1] expmaxchk;
wire expzero; wire expmax;
wire [23:1] manzerochk;
wire manzero; wire mannonzero;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      signff <= 1'b0;
      for (k=1; k <= 8; k = k + 1) begin
        exponentff[k] <= 1'b0;
      end
      for (k=1; k <= 23; k = k + 1) begin
        mantissaff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff <= 1'b0;
        exponentff <= exponentin;
        mantissaff <= mantissain;
      end
    end
  end
  assign expzerochk[1] = exponentff[1];
  assign expmaxchk[1] = exponentff[1];
  genvar k;
  generate for (k=2; k <= 8; k = k + 1) begin: gxa
      assign expzerochk[k] = expzerochk[k - 1] | exponentff[k];
    assign expmaxchk[k] = expmaxchk[k - 1] & exponentff[k];
  end
  endgenerate
  assign expzero =  ~(expzerochk[8]);
  assign expmax = expmaxchk[8];
  assign manzerochk[1] = mantissaff[1];
  genvar k;
  generate for (k=2; k <= 23; k = k + 1) begin: gma
      assign manzerochk[k] = manzerochk[k - 1] | mantissaff[k];
  end
  endgenerate
  assign manzero =  ~(manzerochk[23]);
  assign mannonzero = manzerochk[23];
  assign signout = signff;
  assign exponentout = exponentff;
  assign mantissaout = mantissaff;
  assign satout = expmax & manzero;
  assign zeroout = expzero;
  assign nanout = expmax & mannonzero;
endmodule

module CycleDnCntr(
input wire ClkxC,
input wire RstxRB,
input wire LoadxEI,
input wire [CNTWIDTH - 1:0] CinxDI,
output wire OnxSO,
output wire [CNTWIDTH - 1:0] CoutxDO
);
parameter [31:0] CNTWIDTH;
reg [CNTWIDTH - 1:0] CountxD;
reg NotZeroxS;
  // simple
  always @(CountxD) begin
    // process Comparator
    if(CountxD > 0) begin
      NotZeroxS <= 1'b1;
    end
    else begin
      NotZeroxS <= 1'b0;
    end
  end
  always @(posedge ClkxC, posedge RstxRB) begin
      // process Counter
    if(RstxRB == 1'b0) begin
      // asynchronous reset (active low)
      CountxD <= {((CNTWIDTH - 1)-(0)+1){1'b0}};
    end else begin
      // rising clock edge
      if(NotZeroxS == 1'b1) begin
        CountxD <= CountxD - 1;
      end
      else if(LoadxEI == 1'b1) begin
        // only loadable if count > 0
        CountxD <= CinxDI;
      end
    end
  end
  assign CoutxDO = CountxD;
  assign OnxSO = NotZeroxS;
endmodule

module re_control(
input wire c_clk,
input wire c_rst,
input wire cpu_rd,
input wire cpu_sc,
input wire cpu_pa,
output reg ready,
output reg rd_enable,
output reg [2:0] mux_enable,
output reg rd_strobe
);
parameter [3:0]
  idle = 0,
  hold = 1,
  hold1 = 2,
  read0 = 3,
  read1 = 4,
  read2 = 5,
  read3 = 6,
  read4 = 7,
  finish = 8;
reg [3:0] nState; reg [3:0] cState;
  always @(posedge c_clk, posedge c_rst) begin
    if((c_rst == 1'b1)) begin
      cState <= idle;
    end else begin
      cState <= nState;
    end
  end
  always @(cState, cpu_pa, cpu_sc, cpu_rd) begin : P1
  //, parity, c_cpu_sc
    case(cState)
    idle : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      if(((cpu_sc == 1'b1) && (cpu_pa == 1'b1))) begin
        nState <= hold;
      end
      else begin
        nState <= idle;
      end
    end
    hold : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      if((cpu_rd == 1'b1)) begin
        nState <= hold1;
      end
      else begin
        nState <= idle;
      end
    end
    hold1 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b0;
      ready <= 1'b1;
      mux_enable <= 3'b000;
      nState <= read0;
    end
    read0 : begin
      rd_enable <= 1'b1;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b000;
      nState <= read1;
    end
    read1 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b001;
      nState <= read2;
    end
    read2 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b010;
      nState <= read3;
    end
    read3 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b011;
      nState <= read4;
    end
    read4 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b100;
      nState <= finish;
    end
    finish : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      nState <= idle;
    end
    default : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      nState <= idle;
    end
    endcase
  end
endmodule

module spi_master_slave(
input wire clk_i,
input wire rst_i,
input wire [BYTE_SIZE - 1:0] data_i,
output wire [BYTE_SIZE - 1:0] data_o,
output reg data_valid_o,
input wire wren_i,
input wire [8:0] clk_div_i,
input wire spi_ssn_i,
input wire spi_clk_i,
output reg spi_clk_o,
output reg spi_do_o,
input wire spi_di_i
);
parameter [31:0] BYTE_SIZE=8;
// core interface
// parallel data in (clocked on rising spi_clk after last bit)
// parallel data output (clocked on rising spi_clk after last bit)
// data valid (read / write finished)
// data write enable, starts transmission when interface is idle
// SPI clock divider
// SPI interface
// spi slave select negated input
// spi slave clock input
// spi master clock output
// spi mosi (master mode) or miso (slave mode)
// spi miso (master mode) or mosi (slave mode)
parameter [2:0]
  idle = 0,
  data1 = 1,
  clock1 = 2,
  data2 = 3,
  clock2 = 4,
  sdata1 = 5,
  sdata2 = 6,
  done = 7;
reg [2:0] state;
reg [BYTE_SIZE - 1:0] data_reg;
reg [8:0] clk_cnt;
reg [8:0] counter;
wire fsm_trigger;
  always @(posedge clk_i, posedge rst_i) begin
    if(rst_i == 1'b1) begin
      clk_cnt <= {9{1'b0}};
    end else begin
      if((clk_cnt < clk_div_i)) begin
        clk_cnt <= clk_cnt + 1;
      end
      else begin
        clk_cnt <= {9{1'b0}};
      end
    end
  end
  assign fsm_trigger = clk_cnt == 9'b000000000 || spi_ssn_i == 1'b0 ? 1'b1 : 1'b0;
  always @(posedge clk_i, posedge rst_i, posedge spi_clk_i, posedge fsm_trigger) begin
    if(rst_i == 1'b1) begin
      data_reg <= {((BYTE_SIZE - 1)-(0)+1){1'b0}};
      counter <= {9{1'b0}};
      data_valid_o <= 1'b0;
      spi_clk_o <= 1'b0;
      spi_do_o <= 1'b0;
    end else begin
      if((fsm_trigger == 1'b1)) begin
        case(state)
        idle : begin
          counter <= {9{1'b0}};
          spi_clk_o <= 1'b0;
          spi_do_o <= 1'b0;
          data_valid_o <= 1'b0;
          data_reg <= data_i;
        end
        data1 : begin
          data_valid_o <= 1'b0;
          spi_do_o <= data_reg[BYTE_SIZE - 1];
        end
        clock1 : begin
          spi_clk_o <= 1'b1;
        end
        data2 : begin
          data_reg <= {data_reg[BYTE_SIZE - 2:0],spi_di_i};
        end
        clock2 : begin
          spi_clk_o <= 1'b0;
          counter <= counter + 1;
        end
        sdata1 : begin
          data_valid_o <= 1'b0;
          spi_do_o <= data_reg[BYTE_SIZE - 1];
        end
        sdata2 : begin
          if((spi_clk_i == 1'b0)) begin
            data_reg <= {data_reg[BYTE_SIZE - 2:0],spi_di_i};
            spi_do_o <= data_reg[BYTE_SIZE - 1];
            counter <= counter + 1;
          end
        end
        done : begin
          counter <= {9{1'b0}};
          data_valid_o <= 1'b1;
          spi_do_o <= 1'b0;
        end
        default : begin
        end
        endcase
      end
    end
  end
  assign data_o = data_reg;
  always @(posedge clk_i, posedge rst_i, posedge state, posedge counter, posedge wren_i, posedge spi_ssn_i, posedge spi_clk_i, posedge fsm_trigger) begin
    if(rst_i == 1'b1) begin
      state <= idle;
    end else begin
      if((fsm_trigger == 1'b1)) begin
        case(state)
        idle : begin
          if((spi_ssn_i == 1'b1)) begin
            if((wren_i == 1'b1)) begin
              state <= data1;
            end
          end
          else begin
            state <= sdata1;
          end
        end
        data1 : begin
          state <= clock1;
        end
        clock1 : begin
          state <= data2;
        end
        data2 : begin
          state <= clock2;
        end
        clock2 : begin
          if((counter < (BYTE_SIZE - 1))) begin
            state <= data1;
          end
          else begin
            state <= done;
          end
        end
        sdata1 : begin
          if((spi_clk_i == 1'b1)) begin
            state <= sdata2;
          end
        end
        sdata2 : begin
          if((spi_clk_i == 1'b0)) begin
            if((counter < (BYTE_SIZE - 1))) begin
              state <= sdata1;
            end
            else begin
              state <= done;
            end
          end
        end
        done : begin
          if((spi_ssn_i == 1'b1)) begin
            if((wren_i == 1'b0)) begin
              state <= idle;
            end
          end
          else begin
            if((spi_clk_i == 1'b1)) begin
              state <= sdata1;
            end
          end
        end
        default : begin
        end
        endcase
      end
    end
  end
endmodule

