module counter(
input wire clk,
input wire reset_n
);
parameter [31:0] LEN=1;
reg [31:0] c;
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      c <= 0;
    end else begin
      if(c == (LEN - 1)) begin
        c <= 0;
      end
      else begin
        c <= c + 1;
      end
    end
  end
endmodule

