module CTL_MODULE
(
	CLK, RSTn,
	TX_Done_Sig,
	TX_En_Sig, TX_Data
);
	input CLK;
	input RSTn;
	input TX_Done_Sig;
	output TX_En_Sig;
	output [7:0]TX_Data;
	//// 50M * 1 - 1 = 49_999_999;
	parameter T1S = 26'd49_999_999;
	reg [25:0]Count_Sec;
	always@(posedge CLK or negedge RSTn)
		if (!RSTn)
			Count_Sec <= 26'd0;
		else if (Count_Sec == T1S)
			Count_Sec <= 26'd0;
		else 
			Count_Sec <= Count_Sec + 1'b1;
	///////////////////////////////
	reg isEn;
	reg [7:0]rData;
	always@(posedge CLK or negedge RSTn)
		if (!RSTn)
			begin	
				isEn <= 1'b0;
				rData <= 8'h31;
			end
		else if (TX_Done_Sig)
			begin 
				rData <= 8'd31;
				isEn <= 1'b0;
			end
		else if (Count_Sec == T1S)
			isEn <= 1'b1;
	////////////////////////////////
	assign TX_Data = rData;
	assign TX_En_Sig = isEn;
endmodule

module ps2_keyboard_to_ascii(
input wire clk,
input wire ps2_clk,
input wire ps2_data,
output reg ascii_new,
output reg [6:0] ascii_code
);
parameter [31:0] clk_freq=50000000;
parameter [31:0] ps2_debounce_counter_size=8;
//set such that 2^size/clk_freq = 5us (size = 8 for 50MHz)
//system clock input
//clock signal from PS2 keyboard
//data signal from PS2 keyboard
//output flag indicating new ASCII value
//ASCII value
parameter [1:0]
  ready = 0,
  new_code = 1,
  translate = 2,
  output = 3;
  //needed states
reg [1:0] state;  //state machine
wire ps2_code_new;  //new PS2 code flag from ps2_keyboard component
wire [7:0] ps2_code;  //PS2 code input form ps2_keyboard component
reg prev_ps2_code_new = 1'b1;  //value of ps2_code_new flag on previous clock
reg break = 1'b0;  //'1' for break code, '0' for make code
reg e0_code = 1'b0;  //'1' for multi-code commands, '0' for single code commands
reg caps_lock = 1'b0;  //'1' if caps lock is active, '0' if caps lock is inactive
reg control_r = 1'b0;  //'1' if right control key is held down, else '0'
reg control_l = 1'b0;  //'1' if left control key is held down, else '0'
reg shift_r = 1'b0;  //'1' if right shift is held down, else '0'
reg shift_l = 1'b0;  //'1' if left shift is held down, else '0'
reg [7:0] ascii = 8'hFF;  //internal value of ASCII translation
//declare PS2 keyboard interface component
  //instantiate PS2 keyboard interface logic
  ps2_keyboard #(
      .clk_freq(clk_freq),
    .debounce_counter_size(ps2_debounce_counter_size))
  ps2_keyboard_0(
      .clk(clk),
    .ps2_clk(ps2_clk),
    .ps2_data(ps2_data),
    .ps2_code_new(ps2_code_new),
    .ps2_code(ps2_code));
  always @(posedge clk) begin
    prev_ps2_code_new <= ps2_code_new;
    //keep track of previous ps2_code_new values to determine low-to-high transitions
    case(state)
        //ready state: wait for a new PS2 code to be received
    ready : begin
      if((prev_ps2_code_new == 1'b0 && ps2_code_new == 1'b1)) begin
        //new PS2 code received
        ascii_new <= 1'b0;
        //reset new ASCII code indicator
        state <= new_code;
        //proceed to new_code state
      end
      else begin
        //no new PS2 code received yet
        state <= ready;
        //remain in ready state
      end
      //new_code state: determine what to do with the new PS2 code  
    end
    new_code : begin
      if((ps2_code == 8'hF0)) begin
        //code indicates that next command is break
        break <= 1'b1;
        //set break flag
        state <= ready;
        //return to ready state to await next PS2 code
      end
      else if((ps2_code == 8'hE0)) begin
        //code indicates multi-key command
        e0_code <= 1'b1;
        //set multi-code command flag
        state <= ready;
        //return to ready state to await next PS2 code
      end
      else begin
        //code is the last PS2 code in the make/break code
        ascii[7] <= 1'b1;
        //set internal ascii value to unsupported code (for verification)
        state <= translate;
        //proceed to translate state
      end
      //translate state: translate PS2 code to ASCII value
    end
    translate : begin
      break <= 1'b0;
      //reset break flag
      e0_code <= 1'b0;
      //reset multi-code command flag
      //handle codes for control, shift, and caps lock
      case(ps2_code)
      8'h58 : begin
        //caps lock code
        if((break == 1'b0)) begin
          //if make command
          caps_lock <=  ~caps_lock;
          //toggle caps lock
        end
      end
      8'h14 : begin
        //code for the control keys
        if((e0_code == 1'b1)) begin
          //code for right control
          control_r <=  ~break;
          //update right control flag
        end
        else begin
          //code for left control
          control_l <=  ~break;
          //update left control flag
        end
      end
      8'h12 : begin
        //left shift code
        shift_l <=  ~break;
        //update left shift flag
      end
      8'h59 : begin
        //right shift code
        shift_r <=  ~break;
        //update right shift flag
      end
      default : begin
      end
      endcase
      //translate control codes (these do not depend on shift or caps lock)
      if((control_l == 1'b1 || control_r == 1'b1)) begin
        case(ps2_code)
        8'h1E : begin
          ascii <= 8'h00;
          //^@  NUL
        end
        8'h1C : begin
          ascii <= 8'h01;
          //^A  SOH
        end
        8'h32 : begin
          ascii <= 8'h02;
          //^B  STX
        end
        8'h21 : begin
          ascii <= 8'h03;
          //^C  ETX
        end
        8'h23 : begin
          ascii <= 8'h04;
          //^D  EOT
        end
        8'h24 : begin
          ascii <= 8'h05;
          //^E  ENQ
        end
        8'h2B : begin
          ascii <= 8'h06;
          //^F  ACK
        end
        8'h34 : begin
          ascii <= 8'h07;
          //^G  BEL
        end
        8'h33 : begin
          ascii <= 8'h08;
          //^H  BS
        end
        8'h43 : begin
          ascii <= 8'h09;
          //^I  HT
        end
        8'h3B : begin
          ascii <= 8'h0A;
          //^J  LF
        end
        8'h42 : begin
          ascii <= 8'h0B;
          //^K  VT
        end
        8'h4B : begin
          ascii <= 8'h0C;
          //^L  FF
        end
        8'h3A : begin
          ascii <= 8'h0D;
          //^M  CR
        end
        8'h31 : begin
          ascii <= 8'h0E;
          //^N  SO
        end
        8'h44 : begin
          ascii <= 8'h0F;
          //^O  SI
        end
        8'h4D : begin
          ascii <= 8'h10;
          //^P  DLE
        end
        8'h15 : begin
          ascii <= 8'h11;
          //^Q  DC1
        end
        8'h2D : begin
          ascii <= 8'h12;
          //^R  DC2
        end
        8'h1B : begin
          ascii <= 8'h13;
          //^S  DC3
        end
        8'h2C : begin
          ascii <= 8'h14;
          //^T  DC4
        end
        8'h3C : begin
          ascii <= 8'h15;
          //^U  NAK
        end
        8'h2A : begin
          ascii <= 8'h16;
          //^V  SYN
        end
        8'h1D : begin
          ascii <= 8'h17;
          //^W  ETB
        end
        8'h22 : begin
          ascii <= 8'h18;
          //^X  CAN
        end
        8'h35 : begin
          ascii <= 8'h19;
          //^Y  EM
        end
        8'h1A : begin
          ascii <= 8'h1A;
          //^Z  SUB
        end
        8'h54 : begin
          ascii <= 8'h1B;
          //^[  ESC
        end
        8'h5D : begin
          ascii <= 8'h1C;
          //^\  FS
        end
        8'h5B : begin
          ascii <= 8'h1D;
          //^]  GS
        end
        8'h36 : begin
          ascii <= 8'h1E;
          //^^  RS
        end
        8'h4E : begin
          ascii <= 8'h1F;
          //^_  US
        end
        8'h4A : begin
          ascii <= 8'h7F;
          //^?  DEL
        end
        default : begin
        end
        endcase
      end
      else begin
        //if control keys are not pressed  
        //translate characters that do not depend on shift, or caps lock
        case(ps2_code)
        8'h29 : begin
          ascii <= 8'h20;
          //space
        end
        8'h66 : begin
          ascii <= 8'h08;
          //backspace (BS control code)
        end
        8'h0D : begin
          ascii <= 8'h09;
          //tab (HT control code)
        end
        8'h5A : begin
          ascii <= 8'h0D;
          //enter (CR control code)
        end
        8'h76 : begin
          ascii <= 8'h1B;
          //escape (ESC control code)
        end
        8'h71 : begin
          if((e0_code == 1'b1)) begin
            //ps2 code for delete is a multi-key code
            ascii <= 8'h7F;
            //delete
          end
        end
        default : begin
        end
        endcase
        //translate letters (these depend on both shift and caps lock)
        if(((shift_r == 1'b0 && shift_l == 1'b0 && caps_lock == 1'b0) || ((shift_r == 1'b1 || shift_l == 1'b1) && caps_lock == 1'b1))) begin
          //letter is lowercase
          case(ps2_code)
          8'h1C : begin
            ascii <= 8'h61;
            //a
          end
          8'h32 : begin
            ascii <= 8'h62;
            //b
          end
          8'h21 : begin
            ascii <= 8'h63;
            //c
          end
          8'h23 : begin
            ascii <= 8'h64;
            //d
          end
          8'h24 : begin
            ascii <= 8'h65;
            //e
          end
          8'h2B : begin
            ascii <= 8'h66;
            //f
          end
          8'h34 : begin
            ascii <= 8'h67;
            //g
          end
          8'h33 : begin
            ascii <= 8'h68;
            //h
          end
          8'h43 : begin
            ascii <= 8'h69;
            //i
          end
          8'h3B : begin
            ascii <= 8'h6A;
            //j
          end
          8'h42 : begin
            ascii <= 8'h6B;
            //k
          end
          8'h4B : begin
            ascii <= 8'h6C;
            //l
          end
          8'h3A : begin
            ascii <= 8'h6D;
            //m
          end
          8'h31 : begin
            ascii <= 8'h6E;
            //n
          end
          8'h44 : begin
            ascii <= 8'h6F;
            //o
          end
          8'h4D : begin
            ascii <= 8'h70;
            //p
          end
          8'h15 : begin
            ascii <= 8'h71;
            //q
          end
          8'h2D : begin
            ascii <= 8'h72;
            //r
          end
          8'h1B : begin
            ascii <= 8'h73;
            //s
          end
          8'h2C : begin
            ascii <= 8'h74;
            //t
          end
          8'h3C : begin
            ascii <= 8'h75;
            //u
          end
          8'h2A : begin
            ascii <= 8'h76;
            //v
          end
          8'h1D : begin
            ascii <= 8'h77;
            //w
          end
          8'h22 : begin
            ascii <= 8'h78;
            //x
          end
          8'h35 : begin
            ascii <= 8'h79;
            //y
          end
          8'h1A : begin
            ascii <= 8'h7A;
            //z
          end
          default : begin
          end
          endcase
        end
        else begin
          //letter is uppercase
          case(ps2_code)
          8'h1C : begin
            ascii <= 8'h41;
            //A
          end
          8'h32 : begin
            ascii <= 8'h42;
            //B
          end
          8'h21 : begin
            ascii <= 8'h43;
            //C
          end
          8'h23 : begin
            ascii <= 8'h44;
            //D
          end
          8'h24 : begin
            ascii <= 8'h45;
            //E
          end
          8'h2B : begin
            ascii <= 8'h46;
            //F
          end
          8'h34 : begin
            ascii <= 8'h47;
            //G
          end
          8'h33 : begin
            ascii <= 8'h48;
            //H
          end
