          8'h42 : begin
            ascii <= 8'h4B;
            //K
          end
          8'h4B : begin
            ascii <= 8'h4C;
            //L
          end
          8'h3A : begin
            ascii <= 8'h4D;
            //M
          end
          8'h31 : begin
            ascii <= 8'h4E;
            //N
          end
          8'h44 : begin
            ascii <= 8'h4F;
            //O
          end
          8'h4D : begin
            ascii <= 8'h50;
            //P
          end
          8'h15 : begin
            ascii <= 8'h51;
            //Q
          end
          8'h2D : begin
            ascii <= 8'h52;
            //R
          end
          8'h1B : begin
            ascii <= 8'h53;
            //S
          end
          8'h2C : begin
            ascii <= 8'h54;
            //T
          end
          8'h3C : begin
            ascii <= 8'h55;
            //U
          end
          8'h2A : begin
            ascii <= 8'h56;
            //V
          end
          8'h1D : begin
            ascii <= 8'h57;
            //W
          end
          8'h22 : begin
            ascii <= 8'h58;
            //X
          end
          8'h35 : begin
            ascii <= 8'h59;
            //Y
          end
          8'h1A : begin
            ascii <= 8'h5A;
            //Z
          end
          default : begin
          end
          endcase
        end
        //translate numbers and symbols (these depend on shift but not caps lock)
        if((shift_l == 1'b1 || shift_r == 1'b1)) begin
          //key's secondary character is desired
          case(ps2_code)
          8'h16 : begin
            ascii <= 8'h21;
            //!
          end
          8'h52 : begin
            ascii <= 8'h22;
            //"
          end
          8'h26 : begin
            ascii <= 8'h23;
            //#
          end
          8'h25 : begin
            ascii <= 8'h24;
            //$
          end
          8'h2E : begin
            ascii <= 8'h25;
            //%
          end
          8'h3D : begin
            ascii <= 8'h26;
            //&              
          end
          8'h46 : begin
            ascii <= 8'h28;
            //(
          end
          8'h45 : begin
            ascii <= 8'h29;
            //)
          end
          8'h3E : begin
            ascii <= 8'h2A;
            //*
          end
          8'h55 : begin
            ascii <= 8'h2B;
            //+
          end
          8'h4C : begin
            ascii <= 8'h3A;
            //:
          end
          8'h41 : begin
            ascii <= 8'h3C;
            //<
          end
          8'h49 : begin
            ascii <= 8'h3E;
            //>
          end
          8'h4A : begin
            ascii <= 8'h3F;
            //?
          end
          8'h1E : begin
            ascii <= 8'h40;
            //@
          end
          8'h36 : begin
            ascii <= 8'h5E;
            //^
          end
          8'h4E : begin
            ascii <= 8'h5F;
            //_
          end
          8'h54 : begin
            ascii <= 8'h7B;
            //{
          end
          8'h5D : begin
            ascii <= 8'h7C;
            //|
          end
          8'h5B : begin
            ascii <= 8'h7D;
            //}
          end
          8'h0E : begin
            ascii <= 8'h7E;
            //~
          end
          default : begin
          end
          endcase
        end
        else begin
          //key's primary character is desired
          case(ps2_code)
          8'h45 : begin
            ascii <= 8'h30;
            //0
          end
          8'h16 : begin
            ascii <= 8'h31;
            //1
          end
          8'h1E : begin
            ascii <= 8'h32;
            //2
          end
          8'h26 : begin
            ascii <= 8'h33;
            //3
          end
          8'h25 : begin
            ascii <= 8'h34;
            //4
          end
          8'h2E : begin
            ascii <= 8'h35;
            //5
          end
          8'h36 : begin
            ascii <= 8'h36;
            //6
          end
          8'h3D : begin
            ascii <= 8'h37;
            //7
          end
          8'h3E : begin
            ascii <= 8'h38;
            //8
          end
          8'h46 : begin
            ascii <= 8'h39;
            //9
          end
          8'h52 : begin
            ascii <= 8'h27;
            //'
          end
          8'h41 : begin
            ascii <= 8'h2C;
            //,
          end
          8'h4E : begin
            ascii <= 8'h2D;
            //-
          end
          8'h49 : begin
            ascii <= 8'h2E;
            //.
          end
          8'h4A : begin
            ascii <= 8'h2F;
            ///
          end
          8'h4C : begin
            ascii <= 8'h3B;
            //;
          end
          8'h55 : begin
            ascii <= 8'h3D;
            //=
          end
          8'h54 : begin
            ascii <= 8'h5B;
            //[
          end
          8'h5D : begin
            ascii <= 8'h5C;
            //\
          end
          8'h5B : begin
            ascii <= 8'h5D;
            //]
          end
          8'h0E : begin
            ascii <= 8'h60;
            //`
          end
          default : begin
          end
          endcase
        end
      end
      if((break == 1'b0)) begin
        //the code is a make
        state <= output;
        //proceed to output state
      end
      else begin
        //code is a break
        state <= ready;
        //return to ready state to await next PS2 code
      end
      //output state: verify the code is valid and output the ASCII value
    end
    output : begin
      if((ascii[7] == 1'b0)) begin
        //the PS2 code has an ASCII output
        ascii_new <= 1'b1;
        //set flag indicating new ASCII output
        ascii_code <= ascii[6:0];
        //output the ASCII value
      end
      state <= ready;
      //return to ready state to await next PS2 code
    end
    endcase
  end
endmodule

`timescale 1ns / 1ps
module GraftonCPUPipelineForwarding(
	execute_regval, execute_regid,
	mem_regwrite, mem_regid_d, mem_regval,
	writeback_regwrite, writeback_regid_d, writeback_regval,
	post_wb_regid, post_wb_regval,
	execute_regval_fwd
	);
	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// I/O declarations
	//Input from register file
	input wire[31:0] execute_regval;
	input wire[4:0] execute_regid;
	//Inputs from mem stage
	input wire mem_regwrite;
	input wire[4:0] mem_regid_d;
	input wire[31:0] mem_regval;
	//Inputs from writeback stage
	input wire writeback_regwrite;
	input wire[4:0] writeback_regid_d;
	input wire[31:0] writeback_regval;
	//Inputs from post-writeback state
	input wire[4:0] post_wb_regid;
	input wire[31:0] post_wb_regval;
	//Output to execute stage
	output reg[31:0] execute_regval_fwd = 0;
	////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
	// Forwarding logic
	always @(*) begin
		execute_regval_fwd <= execute_regval;
		//$zero is always zero
		if(execute_regid == 0)
			execute_regval_fwd <= 0;
		//Forward mem stage to execute stage
		else if(mem_regwrite && (mem_regid_d == execute_regid))
			execute_regval_fwd <= mem_regval;
		//Forward writeback stage to execute stage
		else if(writeback_regwrite && (writeback_regid_d == execute_regid))
			execute_regval_fwd <= writeback_regval;
		//Forward post-writeback stage to execute stage
		else if(post_wb_regid == execute_regid)
			execute_regval_fwd <= post_wb_regval;
	end
endmodule

