module select_data(
input wire configuring,
input wire data_acq,
input wire xadc,
input wire we_data,
input wire we_conf,
input wire we_xadc,
input wire [15:0] daq_data_in,
input wire [15:0] conf_data_in,
input wire [15:0] xadc_data_in,
input wire [11:0] data_packet_length,
input wire [11:0] xadc_packet_length,
input wire [11:0] conf_packet_length,
input wire end_packet_conf,
input wire end_packet_daq,
input wire end_packet_xadc,
input wire fifo_rst_daq,
input wire fifo_rst_xadc,
input wire rstFIFO_top,
output reg [15:0] data_out,
output reg [11:0] packet_length,
output reg we,
output reg end_packet,
output wire fifo_rst
);
reg [2:0] sel;
reg fifo_rst_i;
  always @(configuring, data_acq, xadc, we_conf, conf_data_in, conf_packet_length, end_packet_conf, we_data, daq_data_in, data_packet_length, end_packet_daq, fifo_rst_daq, we_xadc, xadc_data_in, xadc_packet_length, end_packet_xadc, fifo_rst_xadc) begin
    sel <= {configuring,data_acq,xadc};
    case(sel)
    3'b100 : begin
      // Configuration
      we <= we_conf;
      data_out <= conf_data_in;
      packet_length <= conf_packet_length;
      end_packet <= end_packet_conf;
      fifo_rst_i <= 1'b0;
    end
    3'b010 : begin
      // DAQ
      we <= we_data;
      data_out <= daq_data_in;
      packet_length <= data_packet_length;
      end_packet <= end_packet_daq;
      fifo_rst_i <= fifo_rst_daq;
    end
    3'b001 : begin
      // XADC
      we <= we_xadc;
      data_out <= xadc_data_in;
      packet_length <= xadc_packet_length;
      end_packet <= end_packet_xadc;
      fifo_rst_i <= fifo_rst_xadc;
    end
    default : begin
      we <= 1'b0;
      data_out <= {16{1'b0}};
      packet_length <= 12'h000;
      end_packet <= 1'b0;
      fifo_rst_i <= 1'b0;
    end
    endcase
  end
  assign fifo_rst = fifo_rst_i | rstFIFO_top;
    // top reset always will work
endmodule

