module audiogen(input  wire clk,
				input  wire reset,
				input  wire adcdat,
				input  wire adclrck,
				input  wire bclk,
				output wire dacdat,
				input  wire daclrck,
				input  wire [3:0] swhi,
				input  wire [3:0] swlo);
	reg [63:0] sample, samplenext;
    reg  oldbclk;
    wire oldbclknext;
    reg  oldlrck;
    wire oldlrcknext;
    wire bclktick;
    wire firstsample;
	always @(posedge clk)
	begin
		sample  = (reset) ? 64'h0 : samplenext;
		oldbclk = (reset) ?  1'h0 : oldbclknext;
		oldlrck = (reset) ?  1'h0 : oldlrcknext;
	end
	assign bclktick    = ( oldbclk & ~bclk);    // negative edge of bclk
	assign firstsample = (~oldlrck & daclrck);  // positive edge of lrck
	assign oldbclknext = bclk;
	assign oldlrcknext = daclrck;
	// --- tone generation logic ---
	reg [7:0] halfperiod, halfperiodnext;
	always @(posedge clk)
	begin
		halfperiod = (reset) ? 7'h0 : halfperiodnext;
	end
	always @(*) 
	begin
	halfperiodnext = halfperiod;
	if (firstsample)
			halfperiodnext = halfperiod + 7'h1;
	if (halfperiodnext == 7'd48)
			halfperiodnext = 7'd0;
	end
	wire [63:0] samplevalue;
	assign samplevalue = (halfperiod < 7'd24) ? 
						 {swhi, 28'h000_0000, swhi, 28'h000_0000} : 
						 {swlo, 28'h000_0000, swlo, 28'h000_0000};
	// --- DAC data shifting logic ---	
	always @(*)
	begin
		samplenext = (firstsample) ? samplevalue :
		             (bclktick)    ? {sample[62:0], 1'b0} : sample;
	end
	assign dacdat = sample[63];
endmodule

`default_nettype none
module display(
    input wire [15:0] number,
    output reg [6:0] seg,
    output reg [3:0] an,
    input wire empty,
    input wire clk
);
integer s = 0;
integer num = 0;
reg [15:0] tmp;
always @(posedge clk) begin
    s <= s + 1;
    case (s)
    0 : begin
        an <= 4'b1111;
        if (empty)
            seg <= 7'h3f;
        else case (tmp[3:0])
            4'h0: seg <= 7'h40;
            4'h1: seg <= 7'h79;
            4'h2: seg <= 7'h24;
            4'h3: seg <= 7'h30;
            4'h4: seg <= 7'h19;
            4'h5: seg <= 7'h12;
            4'h6: seg <= 7'h02;
            4'h7: seg <= 7'h78;
            4'h8: seg <= 7'h00;
            4'h9: seg <= 7'h10;
            4'ha: seg <= 7'h08;
            4'hb: seg <= 7'h03;
            4'hc: seg <= 7'h46;
            4'hd: seg <= 7'h21;
            4'he: seg <= 7'h06;
            4'hf: seg <= 7'h0e;
        endcase
    end
    10 : an <= ~(1 << num);
    90 : begin
        an <= 4'b1111;
        if (num == 3) begin
            num <= 0; 
            tmp <= number;
        end
        else begin
            num <= num + 1;
            tmp <= tmp >> 4;
        end
    end
    100 : s <= 0;
    endcase
end
endmodule

module pwm10bit(
input wire clk,
input wire adc_samplingrate,
input wire [2:0] adc_channel,
input wire adc_miso,
output wire adc_mosi,
output wire adc_cs,
output wire adc_clk,
output wire [15:0] adc_value,
output wire adc_valid,
output reg pwm_out
);
// ADC SPI MISO
// ADC SPI MOSI
// ADC SPI CHIP SELECT
// ADC SPI CLOCK
// From http://www.micro-nova.com/resources/
reg [31:0] threshold = 0;
reg [31:0] counter = 0;
wire [9:0] adc_out;
wire adc_pulse;
  // map to output and extend to 16 bits
  assign adc_value = {6'b000000,adc_out};
  assign adc_valid = adc_pulse;
  MercuryADC adc(
      // command input
    .clock(clk),
    // from onboard oscillator
    .trigger(adc_samplingrate),
    // assert to sample ADC
    .diffn(1'b1),
    // single/differential inputs
    .channel(adc_channel),
    // channel to sample (3 == light sensor)
    // data output
    .Dout(adc_out),
    // data from ADC
    .OutVal(adc_pulse),
    // pulsed when data sampled
    // ADC connection
    .adc_miso(adc_miso),
    // ADC SPI MISO
    .adc_mosi(adc_mosi),
    // ADC SPI MOSI
    .adc_cs(adc_cs),
    // ADC SPI CHIP SELECT
    .adc_clk(adc_clk));
  always @(adc_pulse) begin
    if((adc_pulse == 1'b1)) begin
      threshold <= adc_out;
    end
  end
  always @(posedge clk) begin
    counter <= counter + 1;
    // just let it wrap around
    if((counter > threshold)) begin
      pwm_out <= 1'b0;
    end
    else begin
      pwm_out <= 1'b1;
    end
  end
endmodule

module ALU(input [15:0] R1, R2, input [2:0] controlSignal, output reg[15:0] out, output reg zero);
  always @(*) begin
    zero = 0;
    case (controlSignal)
    	0: out = R2;
    	1: out = R1 + R2;
    	2: out = R1 - R2;
    	3: out = R1 & R2;
    	4: out = R1 | R2;
    	5: out = ~R2;
    	6: begin
            out = R1; 
            if (R1 == R2) zero = 1;
        end
    	7: out = R1;
    	default: out = R1;
    endcase
  end
endmodule

module alu(
input wire [3:0] alu_ctrl,
input wire [31:0] alu_src1,
input wire [31:0] alu_src2,
output reg alu_zero,
output reg [31:0] alu_result,
output wire alu_carry
);
  always @(alu_src1, alu_src2, alu_ctrl) begin : P1
    reg [31:0] src1, src2, result;
    reg zero;
    //
    src1 = alu_src1;
    src2 = alu_src2;
    result = {1{1'b0}};
    zero = 1'b0;
    //
    case(alu_ctrl)
        //AND
    4'b0000 : begin
      result = src1 & src2;
      //OR
    end
    4'b0001 : begin
      result = src1 | src2;
      //ADD
    end
    4'b0010 : begin
      result = src1 + src2;
      //SUB
    end
    4'b0110 : begin
      result = src1 - src2;
      //SLT
    end
    4'b0111 : begin
      if(src1 < src2) begin
        result[0] = 1'b1;
      end
      else begin
        result[0] = 1'b0;
      end
      //NOR
    end
    4'b1100 : begin
      result =  ~(src1 | src2);
      //error
    end
    default : begin
      result = {1{1'b0}};
    end
    endcase
    if((result) == 0) begin
      zero = 1'b1;
    end
    else begin
      zero = 1'b0;
    end
    alu_result <= result;
    alu_zero <= zero;
  end
endmodule

module EPROC_IN4(
