      .busyOut(busyOut));
    //-----------------------------------------------------------------------------------------
    // ENCODING case "10": HDLC
    //-----------------------------------------------------------------------------------------
    // TBD
    assign DATA_OUT_HDLC_decoded = {10{1'b0}};
    assign DATA_RDY_HDLC_decoded = 1'b0;
    //-----------------------------------------------------------------------------------------
    // output data/rdy according to the encoding settings
    //-----------------------------------------------------------------------------------------
    MUX4_Nbit #(
          .N(10))
    DATA_OUT_MUX4_10bit(
          .data0(DATA_OUT_direct),
      .data1(DATA_OUT_8b10b_decoded),
      .data2(DATA_OUT_HDLC_decoded),
      .data3(zeros10array),
      .sel(ENCODING),
      .data_out(DATA_OUT_s));
    MUX4 DATA_RDY_MUX4(
          .data0(DATA_RDY_direct),
      .data1(DATA_RDY_8b10b_decoded),
      .data2(DATA_RDY_HDLC_decoded),
      .data3(1'b0),
      .sel(ENCODING),
      .data_out(DATA_RDY_sig));
    assign DATA_RDY = DATA_RDY_sig;
    assign DATA_OUT = DATA_OUT_s;
        //------------------
  end
  endgenerate
  //
  //
  generate if (do_generate == false) begin: gen_disabled
      assign DATA_OUT = {10{1'b0}};
    assign DATA_RDY = 1'b0;
    assign busyOut = 1'b0;
  end
  endgenerate
