module tcp_engine_session_filter(
input wire clk,
input wire [15:0] listen_port,
input wire drop_connection,
output wire connected,
input wire in_data_valid,
input wire [7:0] in_data,
input wire in_hdr_valid,
input wire [31:0] in_src_ip,
input wire [15:0] in_src_port,
input wire [15:0] in_dst_port,
input wire [31:0] in_seq_num,
input wire [31:0] in_ack_num,
input wire [15:0] in_window,
input wire in_flag_urg,
input wire in_flag_ack,
input wire in_flag_psh,
input wire in_flag_rst,
input wire in_flag_syn,
input wire in_flag_fin,
input wire [15:0] in_urgent_ptr,
output reg out_data_valid,
output reg [7:0] out_data,
output reg out_hdr_valid,
output wire [31:0] out_from_ip,
output wire [15:0] out_from_port,
output reg [31:0] out_seq_num,
output reg [31:0] out_ack_num,
output reg [15:0] out_window,
output reg out_flag_urg,
output reg out_flag_ack,
output reg out_flag_psh,
output reg out_flag_rst,
output reg out_flag_syn,
output reg out_flag_fin,
output reg [15:0] out_urgent_ptr
);
// data received over TCP/IP
reg i_connected = 1'b0;
reg do_drop = 1'b0;
reg [15:0] session_src_port = 1'b0;
reg [31:0] session_src_ip = 1'b0;
  assign connected = i_connected;
  assign out_from_ip = session_src_ip;
  assign out_from_port = session_src_port;
  always @(posedge clk) begin
    if(i_connected == 1'b1) begin
      if(do_drop == 1'b1 && in_data_valid == 1'b0 && in_hdr_valid == 1'b0) begin
        // Drop the connection
        i_connected <= 1'b0;
        out_data_valid <= 1'b0;
        out_hdr_valid <= 1'b0;
        do_drop <= 1'b0;
      end
      else begin
        if(in_dst_port == listen_port && in_src_ip == session_src_ip && in_src_port == session_src_port) begin
          out_data_valid <= in_data_valid;
          out_hdr_valid <= in_hdr_valid;
        end
        else begin
          out_data_valid <= 1'b0;
          out_hdr_valid <= 1'b0;
        end
      end
    end
    else begin
      if(in_hdr_valid == 1'b1) begin
        if(in_dst_port == listen_port && in_flag_syn == 1'b1) begin
          i_connected <= 1'b1;
          session_src_port <= in_src_port;
          session_src_ip <= in_src_ip;
          out_data_valid <= in_data_valid;
          out_hdr_valid <= in_hdr_valid;
        end
      end
    end
    // Copy non-key data over anyway (just don't assert the valid siganls!
    out_data <= in_data;
    out_seq_num <= in_seq_num;
    out_ack_num <= in_ack_num;
    out_window <= in_window;
    out_flag_urg <= in_flag_urg;
    out_flag_ack <= in_flag_ack;
    out_flag_psh <= in_flag_psh;
    out_flag_rst <= in_flag_rst;
    out_flag_syn <= in_flag_syn;
    out_flag_fin <= in_flag_fin;
    out_urgent_ptr <= in_urgent_ptr;
    // Remember if we are asked to drop the connection
    if(do_drop == 1'b0) begin
      do_drop <= drop_connection;
    end
  end
endmodule

module arbiter(
input wire [0:C_NR_SLOTS - 1] i_ready,
input wire [0:C_NR_SLOTS - 1] i_req_0,
input wire [0:C_NR_SLOTS - 1] i_req_1,
input wire [0:C_NR_SLOTS - 1] i_req_2,
output wire [0:C_NR_SLOTS - 1] o_grant_0,
output wire [0:C_NR_SLOTS - 1] o_grant_1,
output wire [0:C_NR_SLOTS - 1] o_grant_2,
input wire clk,
input wire reset
);
parameter [31:0] C_NR_SLOTS=3;
// it is not a "real" generic, e.g., we still have to adapt the number of ports and the number of signals manually
//every thread can tell whether it is ready to accept data
//requests vector of thread Nr 0 (0 to 0 is allowed, loops are explicitly allowed)
//requests vector of thread Nr. 1. (element 0 = 1 => want to talk with thread 0)
//requests vector of thread Nr. 2.
//grant vector to thread NR 0. (element 0 = 1 => allowed to talk to thread 0)
//grant vector to thread NR 1. (element 0 = 1 => allowed to talk to thread 0)
//grant vector to thread Nr 2. (element 0 = 1 => allowed to talk to thread 0)
wire [0:C_NR_SLOTS - 1] req_for_thread_0;  // request signals for talking with thread 0
wire [0:C_NR_SLOTS - 1] req_for_thread_1;  // element 0 = 1 => thread 0 wants to talk to thread 1
wire [0:C_NR_SLOTS - 1] req_for_thread_2;
reg [0:C_NR_SLOTS - 1] grant_for_thread_0;  // grant signals for talking with thread 0
reg [0:C_NR_SLOTS - 1] grant_for_thread_1;  // element 0 = 1 => thread 0 is allowed to talk to thread 1
reg [0:C_NR_SLOTS - 1] grant_for_thread_2;
parameter [2:0]
  STATE_INIT = 0,
  STATE_WAIT = 1,
  STATE_GRANT_0 = 2,
  STATE_GRANT_1 = 3,
  STATE_GRANT_2 = 4;
reg [2:0] b0_state = STATE_INIT;
reg [2:0] b0_state_next = STATE_INIT;
reg [2:0] b1_state = STATE_INIT;
reg [2:0] b1_state_next = STATE_INIT;
reg [2:0] b2_state = STATE_INIT;
reg [2:0] b2_state_next = STATE_INIT;
  // how could this be done less ugly?...
  assign req_for_thread_0[0] = i_req_0[0];
  assign req_for_thread_0[1] = i_req_1[0];
  assign req_for_thread_0[2] = i_req_2[0];
  assign req_for_thread_1[0] = i_req_0[1];
  //	'1'
  assign req_for_thread_1[1] = i_req_1[1];
  //	'0'
  assign req_for_thread_1[2] = i_req_2[1];
  // 	'0'	
  assign req_for_thread_2[0] = i_req_0[2];
  assign req_for_thread_2[1] = i_req_1[2];
  assign req_for_thread_2[2] = i_req_2[2];
  assign o_grant_0[0] = grant_for_thread_0[0];
  assign o_grant_0[1] = grant_for_thread_1[0];
  assign o_grant_0[2] = grant_for_thread_2[0];
  assign o_grant_1[0] = grant_for_thread_0[1];
  assign o_grant_1[1] = grant_for_thread_1[1];
  assign o_grant_1[2] = grant_for_thread_2[1];
  assign o_grant_2[0] = grant_for_thread_0[2];
  //0
  assign o_grant_2[1] = grant_for_thread_1[2];
  //1
  assign o_grant_2[2] = grant_for_thread_2[2];
  //0
  //computes the grant signal for bus_0 (e.g. determines who is allowed to send to the hwthread in slot 0.
  always @(req_for_thread_0, b0_state) begin
    b0_state_next <= b0_state;
    case(b0_state)
    STATE_INIT : begin
      b0_state_next <= STATE_WAIT;
      grant_for_thread_0 <= {((C_NR_SLOTS - 1)-(0)+1){1'b0}};
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_0[0] == 1'b1) begin
        b0_state_next <= STATE_GRANT_0;
        grant_for_thread_0 <= 3'b100;
      end
      else if(req_for_thread_0[1] == 1'b1) begin
        b0_state_next <= STATE_GRANT_1;
        grant_for_thread_0 <= 3'b010;
      end
      else if(req_for_thread_0[2] == 1'b1) begin
        b0_state_next <= STATE_GRANT_2;
        grant_for_thread_0 <= 3'b001;
      end
      else begin
        b0_state_next <= STATE_WAIT;
        grant_for_thread_0 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[0] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b100;
        b0_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[1] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b010;
        b0_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[2] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b001;
        b0_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b0_state_next <= STATE_INIT;
    end
    endcase
  end
  //	grant_for_thread_1 <= "100";
  //computes the grant signal for bus_0 (e.g. determines who is allowed to send to the hwthread in slot 0.
  always @(req_for_thread_1, b1_state) begin
    b1_state_next <= b1_state;
    grant_for_thread_1 <= 3'b000;
    case(b1_state)
    STATE_INIT : begin
      b1_state_next <= STATE_WAIT;
      grant_for_thread_1 <= 3'b000;
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_1[0] == 1'b1) begin
        b1_state_next <= STATE_GRANT_0;
        grant_for_thread_1 <= 3'b100;
      end
      else if(req_for_thread_1[1] == 1'b1) begin
        b1_state_next <= STATE_GRANT_1;
        grant_for_thread_1 <= 3'b010;
      end
      else if(req_for_thread_1[2] == 1'b1) begin
        b1_state_next <= STATE_GRANT_2;
        grant_for_thread_1 <= 3'b001;
      end
      else begin
        b1_state_next <= STATE_WAIT;
        grant_for_thread_1 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[0] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b100;
        b1_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[1] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b010;
        b1_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[2] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b001;
        b1_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b1_state_next <= STATE_INIT;
    end
    endcase
  end
  always @(req_for_thread_2, b2_state) begin
    b2_state_next <= b2_state;
    case(b2_state)
    STATE_INIT : begin
      b2_state_next <= STATE_WAIT;
      grant_for_thread_2 <= {((C_NR_SLOTS - 1)-(0)+1){1'b0}};
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_2[0] == 1'b1) begin
        b2_state_next <= STATE_GRANT_0;
        grant_for_thread_2 <= 3'b100;
      end
      else if(req_for_thread_2[1] == 1'b1) begin
        b2_state_next <= STATE_GRANT_1;
        grant_for_thread_2 <= 3'b010;
      end
      else if(req_for_thread_2[2] == 1'b1) begin
        b2_state_next <= STATE_GRANT_2;
        grant_for_thread_2 <= 3'b001;
      end
      else begin
        b2_state_next <= STATE_WAIT;
        grant_for_thread_2 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[0] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b100;
        b2_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[1] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b010;
        b2_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[2] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b001;
        b2_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b2_state_next <= STATE_INIT;
    end
    endcase
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      b0_state <= STATE_INIT;
      b1_state <= STATE_INIT;
      b2_state <= STATE_INIT;
    end else begin
      b0_state <= b0_state_next;
      b1_state <= b1_state_next;
      b2_state <= b2_state_next;
    end
  end
endmodule

