module gfmapinv(
input wire [3:0] ah,
input wire [3:0] al,
output wire [7:0] a
);
// ah -> High Data Input (4 std_logic)
// al -> Low Data Input (4 std_logic)
// a -> Data Output (remapped back) (8 std_logic)
// Architecture of the Component
  // Inverse Mapping Process
  assign a[0] = al[0] ^ ah[0];
  assign a[1] = ah[0] ^ ah[1] ^ ah[3];
  assign a[2] = al[1] ^ ah[3] ^ ah[0] ^ ah[1];
  assign a[3] = ah[0] ^ ah[1] ^ al[1] ^ ah[2];
  assign a[4] = al[1] ^ ah[3] ^ ah[0] ^ ah[1] ^ al[3];
  assign a[5] = ah[0] ^ ah[1] ^ al[2];
  assign a[6] = al[1] ^ ah[3] ^ al[2] ^ al[3] ^ ah[0];
  assign a[7] = ah[0] ^ ah[1] ^ al[2] ^ ah[3];
endmodule

