module sounds(
input wire clk,
input wire reset,
input wire enable,
input wire [18:0] period,
input wire [2:0] volume,
output wire speaker
);
reg [18:0] counter; wire [18:0] counter_next;
wire [17:0] pulse_width;
  always @(negedge clk, negedge reset) begin
    if(reset == 1'b1) begin
      counter <= {19{1'b0}};
    end else begin
      counter <= counter_next;
    end
  end
  // duty cycle:
  //    max:   50% (18 downto 1)
  //    min: 0.78% (18 downto 7)
  //    off when given 0 (18 downto 0)!
  assign pulse_width = period[18:volume];
  assign counter_next = counter == period ? {19{1'b0}} : counter + 1;
  assign speaker = (enable == 1'b1 && counter < pulse_width) ? 1'b1 : 1'b0;
endmodule

module ALU #(parameter DATAWIDTH=8, FUNC = 4) 
(
input 										CLK,
input 										RST,
input		[DATAWIDTH-1:0] 				A,
input		[DATAWIDTH-1:0]					B,
input		[FUNC-1:0]						ALU_FUNC,
input										Enable,
output reg		[2*DATAWIDTH-1:0]				ALU_OUT,
output reg										OUT_VALID
);
reg 		[2*DATAWIDTH-1:0]				ALU_OUT_comb;
reg											OUT_VALID_comb;
parameter Addition=4'b0000, Subtraction =4'b0001, Multiplication=4'b010,Division=4'b011,AND =4'b100, OR = 4'b101, NAND = 4'b110, NOR = 4'b111, XOR = 4'b1000, XNOR=4'b1001 , CMPEQN = 4'b1010 , CMPGREATER=4'b1011 ,CMPSMALLER=4'b1100 , SHIFTLEFT=4'b1101 ,SHIFTRIGHT = 4'b1110;
always@(posedge CLK or negedge RST)
begin
		if(!RST) begin ALU_OUT<='b0; OUT_VALID<='b1;   end
		else begin  ALU_OUT<= ALU_OUT_comb; OUT_VALID<=OUT_VALID_comb;    end 
end
always@(*)
	begin
		 if(Enable) begin
		 OUT_VALID_comb<='b1;
			case(ALU_FUNC)
				Addition:					ALU_OUT_comb<= A+B;
				Subtraction:				ALU_OUT_comb<= A-B;
				Multiplication:				ALU_OUT_comb<= A*B;
				Division:					ALU_OUT_comb<= A/B;					
				AND:						ALU_OUT_comb<= A&B;
				OR:							ALU_OUT_comb<= A|B;
				NAND:						ALU_OUT_comb<= !(A&B);
				NOR:						ALU_OUT_comb<= !(A|B);
				XOR:						ALU_OUT_comb<= A^B;
				XNOR:						ALU_OUT_comb<= !(A^B);
				CMPEQN:						ALU_OUT_comb<= (A===B);
				CMPGREATER:		begin		if(A>B) ALU_OUT_comb<=2; else  ALU_OUT_comb<=0;  end
				CMPSMALLER:		begin		if(A<B) ALU_OUT_comb<=3; else  ALU_OUT_comb<=0;  end
				SHIFTLEFT:					ALU_OUT_comb<= A<<1;
				SHIFTRIGHT:					ALU_OUT_comb<= A>>1;
				default:					ALU_OUT_comb<=0; 
			endcase
		end
		else
		begin
		OUT_VALID_comb<='b0;
		end
	end
endmodule

module cc(
    input   wire        clk,
    input   wire        rst,
    input   wire        in_e,
    input   wire[31:0]  in_a,
    input   wire[31:0]  in_d,
    output  reg[31:0]   mct_a,
    input   wire        ls_load,
    input   wire[31:0]  ou_a,
    output  reg[31:0]   ou_d,
    output  reg         ou_hit,
    input   wire        stl
);
    `define ICACHE_SIZE 7
    integer   i;
    (*ram_style = "registers"*) reg[15 - `ICACHE_SIZE + 1 + 31:0] cache[2 ** `ICACHE_SIZE - 1:0];
    reg     ls_stl;
    always @ (posedge clk) begin
        ls_stl <= stl;
    end
    always @ (*) begin
        if (rst == 0) begin
            if (ls_load == 0 && cache[ou_a[`ICACHE_SIZE + 1: 2]][47 - `ICACHE_SIZE: 32] == {ou_a[16: `ICACHE_SIZE + 2], 1'b1}) begin
                if (ls_stl == 0) begin
                    ou_d = cache[ou_a[`ICACHE_SIZE + 1 : 2]][31: 0];
                    ou_hit = 1;
                    mct_a = 1;
//                    $display("CACHE HIT %d %h %h", $time, ou_a, ou_d);
                end else begin
                    ou_d = 0;
                    ou_hit = 0;
                    mct_a = 1;
                end
            end else begin
                ou_d = 0;
                ou_hit = 0;
                mct_a = ou_a;
            end
        end else begin
            ou_hit = 0;
            ou_d = 0;
            mct_a = 1;
        end
    end
    always @ (posedge clk) begin
        if (rst == 0) begin
            if (in_e == 1) begin
                cache[in_a[`ICACHE_SIZE + 1 :2]] <= {in_a[16: `ICACHE_SIZE + 2], 1'h1, in_d};
//                $display("CACHE WRITE %d %h %h", $time, in_a, in_d);
            end
        end else begin
            for (i = 0; i < (2 ** `ICACHE_SIZE); i = i + 1) cache[i] <= 0;
        end
    end
endmodule

module top(
input wire clk_50MHz,
input wire rst,
input wire init_ini,
input wire bt_db,
output wire init_fin_led,
output wire hsync,
output wire vsync,
output wire [2:0] vga_red,
output wire [2:0] vga_green,
output wire [1:0] vga_blue,
output wire [3:0] disp7seg_sel,
output wire [6:0] disp7seg_data,
output wire [2:0] ram_data_leds,
input wire [1:0] sw_debug
);
// =================================================================================
//           ARCHITECTURE
// =================================================================================
//----------------------------------------------------------------------------------
// Componentes
//----------------------------------------------------------------------------------
//----------------------------------------------------------------------------------
// Declaración de señales
//----------------------------------------------------------------------------------
// Senales auxiliares (pos. pantalla VGA)
wire [9:0] pos_h_aux;
wire [9:0] pos_v_aux;  //--------------------------------------------------------
// Puerto 0 de solo escritura (inicializacion y fanstasma)
//--------------------------------------------------------
// Conexiones directas a los puertos de la RAM
reg [5:0] ram_addr_0;
reg [2:0] ram_data_0;
reg ram_wr_0;  // Conexiones procedentes del módulo de inicialización:
wire [5:0] ram_addr_0_init;
wire [2:0] ram_data_0_init;
wire ram_wr_0_init;  // Conexiones procedentes del primer fantasma:
wire [5:0] ram_addr_0_f1;
wire [2:0] ram_data_0_f1;
wire ram_wr_0_f1;  // Conexiones procedentes del segundo fantasma:
wire [5:0] ram_addr_0_f2;
wire [2:0] ram_data_0_f2;
wire ram_wr_0_f2;  // Conexiones procedentes del tercer fantasma:
wire [5:0] ram_addr_0_f3;
wire [2:0] ram_data_0_f3;
wire ram_wr_0_f3;  //--------------------------------------------------------
// Puerto 1 de solo lectura: lectura VGA
//--------------------------------------------------------
wire [5:0] ram_addr_1;
wire [2:0] ram_data_1;  //--------------------------------------------------------
// Puerto 2 de solo lectura: lectura fantasmas
//--------------------------------------------------------
// Conexiones directas a los puertos de la RAM:
reg [5:0] ram_addr_2;
wire [2:0] ram_data_2;  // Conexiones procedentes del primer fantasma:
wire [5:0] ram_addr_2_f1;
reg [2:0] ram_data_2_f1;  // Conexiones procedentes del segundo fantasma:
wire [5:0] ram_addr_2_f2;
reg [2:0] ram_data_2_f2;  // Conexiones procedentes del tercer fantasma:
wire [5:0] ram_addr_2_f3;
reg [2:0] ram_data_2_f3;  //--------------------------------------------------------
// Señales de la FSM principal:
//--------------------------------------------------------
parameter [2:0]
  s0 = 0,
  s1 = 1,
  fantasma1_st = 2,
  fantasma2_st = 3,
  fantasma3_st = 4;
reg [2:0] current_state; reg [2:0] next_state;  // Estados actual y siguiente
wire init_fin;
reg start_fantasma1;
wire fin_fantasma1;
reg start_fantasma2;
wire fin_fantasma2;
reg start_fantasma3;
wire fin_fantasma3;  //--------------------------------------------------------
// Señales Auxiliares:
//--------------------------------------------------------
// Señales de reloj auxiliares:
wire clk_1KHz_aux;
wire pulso_2Hz_aux;  // Señales de depuración:
wire [5:0] ram_addr_debug;
wire [15:0] ram_addr_debug_ext;
wire [2:0] fantasma_debug_data;
wire bt_db_deb;  // Otros
wire [1:0] rand_aux;
  //----------------------------------------------------------------------------------
  // Conexión de señales
  //----------------------------------------------------------------------------------
  // La direccion de lectura depende de las coordenadas:
  assign ram_addr_1 = {pos_v_aux[6:4],pos_h_aux[6:4]};
  //Lectura VGA
  assign init_fin_led = init_fin;
  assign ram_addr_debug_ext = {5'b00000,fantasma_debug_data,2'b00,ram_addr_debug};
  assign rand_aux = {pos_v_aux[3],pos_v_aux[2]};
  //----------------------------------------------------------------------------------
  // Conexión de componentes
  //----------------------------------------------------------------------------------
  sincronismo Inst_sincronismo(
      .clk_50MHz(clk_50MHz),
    .rst(rst),
    .hsync(hsync),
    .vsync(vsync),
    .pos_h(pos_h_aux),
    .pos_v(pos_v_aux));
  rgb_conv Inst_rgb_conv(
      .r(ram_data_1[2]),
    .g(ram_data_1[1]),
    .b(ram_data_1[0]),
    .pos_h(pos_h_aux),
    .pos_v(pos_v_aux),
    .r_out(vga_red),
    .g_out(vga_green),
    .b_out(vga_blue));
  init_ram Inst_init_ram(
      .clk_50MHz(clk_50MHz),
    .rst(rst),
    .ini(init_ini),
    .ram_addr(ram_addr_0_init),
    .ram_data(ram_data_0_init),
    .ram_we(ram_wr_0_init),
    .fin(init_fin));
  ram_dp_sr_sw Inst_ram_dp_sr_sw(
      .rst(rst),
    .clk(clk_50MHz),
    // Puerto 0: solo escritura. (inicializacion y fantasma)
    .address_0(ram_addr_0),
    .data_0(ram_data_0),
    .wr_0(ram_wr_0),
    // Puerto 1: solo lectura (VGA)
    .address_1(ram_addr_1),
    .data_1(ram_data_1),
    // Puerto 2: solo lectura (fantasma)
    .address_2(ram_addr_2),
    .data_2(ram_data_2),
    // Puertos de depuración
    .bt_ld(bt_db_deb),
    .addr_db(ram_addr_debug),
    .data_db(ram_data_leds));
  freqDividerV3 Inst_freqDividerV3(
      .clk(clk_50MHz),
    .rst(rst),
    .clk_1KHz(clk_1KHz_aux),
    .pulso_2Hz(pulso_2Hz_aux));
  debouncer Inst_debouncer(
      .clk(clk_50MHz),
    .rst(rst),
    .x(bt_db),
    .pulso2Hz(pulso_2Hz_aux),
    .xDeb(bt_db_deb));
  control7seg Inst_control7seg(
      .clk_1KHz(clk_1KHz_aux),
    .rst(rst),
    .data_in(ram_addr_debug_ext),
    .data_out(disp7seg_data),
    .sel(disp7seg_sel));
  fantasma_v0 fantasma1(
      .clk_50MHz(clk_50MHz),
    .rst(rst),
    .p2Hz(pulso_2Hz_aux),
    .ini(start_fantasma1),
    .fin(fin_fantasma1),
    .ram_addr_rd(ram_addr_2_f1),
    .ram_data_rd(ram_data_2_f1),
    .ram_addr_wr(ram_addr_0_f1),
    .ram_data_wr(ram_data_0_f1),
    .ram_we(ram_wr_0_f1),
    .sw_debug(sw_debug),
    .data_db(fantasma_debug_data),
    .bt_rand(rand_aux));
  fantasma2 Inst_fantasma2(
      .clk_50MHz(clk_50MHz),
    .rst(rst),
    .p2Hz(pulso_2Hz_aux),
    .ini(start_fantasma2),
    .fin(fin_fantasma2),
    .ram_addr_rd(ram_addr_2_f2),
    .ram_data_rd(ram_data_2_f2),
    .ram_addr_wr(ram_addr_0_f2),
    .ram_data_wr(ram_data_0_f2),
    .ram_we(ram_wr_0_f2),
    .bt_rand(rand_aux));
  fantasma3 Inst_fantasma3(
      .clk_50MHz(clk_50MHz),
    .rst(rst),
    .p2Hz(pulso_2Hz_aux),
    .ini(start_fantasma3),
    .fin(fin_fantasma3),
    .ram_addr_rd(ram_addr_2_f3),
    .ram_data_rd(ram_data_2_f3),
    .ram_addr_wr(ram_addr_0_f3),
    .ram_data_wr(ram_data_0_f3),
    .ram_we(ram_wr_0_f3),
    .bt_rand(rand_aux));
  //----------------------------------------------------------------------------------
  // Procesos
  //----------------------------------------------------------------------------------
  //-------------------------------------------------
  // Cálculo del estado siguiente y salidas Mealy
  //-------------------------------------------------
  always @(current_state, init_fin, init_ini, fin_fantasma1, fin_fantasma2, fin_fantasma3) begin
    case(current_state)
    s0 : begin
      start_fantasma1 <= 1'b0;
      start_fantasma2 <= 1'b0;
      start_fantasma3 <= 1'b0;
      if(init_ini == 1'b1) begin
        next_state <= s1;
      end
      else begin
        next_state <= s0;
      end
    end
    s1 : begin
      start_fantasma2 <= 1'b0;
      start_fantasma3 <= 1'b0;
      if(init_fin == 1'b1) begin
        start_fantasma1 <= 1'b1;
        next_state <= fantasma1_st;
      end
      else begin
        start_fantasma1 <= 1'b0;
        next_state <= s1;
      end
    end
    fantasma1_st : begin
      start_fantasma1 <= 1'b0;
      start_fantasma3 <= 1'b0;
      if(fin_fantasma1 == 1'b1) begin
        start_fantasma2 <= 1'b1;
        next_state <= fantasma2_st;
      end
      else begin
        start_fantasma2 <= 1'b0;
        next_state <= current_state;
      end
    end
    fantasma2_st : begin
      start_fantasma1 <= 1'b0;
      start_fantasma2 <= 1'b0;
      if(fin_fantasma2 == 1'b1) begin
        start_fantasma3 <= 1'b1;
        next_state <= fantasma3_st;
      end
      else begin
        start_fantasma3 <= 1'b0;
        next_state <= current_state;
      end
    end
    fantasma3_st : begin
      start_fantasma2 <= 1'b0;
      start_fantasma3 <= 1'b0;
      if(fin_fantasma3 == 1'b1) begin
        start_fantasma1 <= 1'b1;
        next_state <= fantasma1_st;
      end
      else begin
        start_fantasma1 <= 1'b0;
        next_state <= current_state;
      end
    end
    endcase
  end
  //-------------------------------------------------
  // Multiplexor de la escritura en RAM (compartida por fantasmas e inicializacion)
  //-------------------------------------------------
  always @(current_state, ram_wr_0_f1, ram_addr_0_f1, ram_data_0_f1, ram_wr_0_f2, ram_addr_0_f2, ram_data_0_f2, ram_wr_0_f3, ram_addr_0_f3, ram_data_0_f3, ram_wr_0_init, ram_addr_0_init, ram_data_0_init) begin
    if(current_state == fantasma1_st) begin
      //Game
      ram_wr_0 <= ram_wr_0_f1;
      ram_addr_0 <= ram_addr_0_f1;
      ram_data_0 <= ram_data_0_f1;
    end
    else if(current_state == fantasma2_st) begin
      ram_wr_0 <= ram_wr_0_f2;
      ram_addr_0 <= ram_addr_0_f2;
      ram_data_0 <= ram_data_0_f2;
    end
    else if(current_state == fantasma3_st) begin
      ram_wr_0 <= ram_wr_0_f3;
      ram_addr_0 <= ram_addr_0_f3;
      ram_data_0 <= ram_data_0_f3;
    end
    else if(current_state == s1) begin
      ram_wr_0 <= ram_wr_0_init;
      ram_addr_0 <= ram_addr_0_init;
      ram_data_0 <= ram_data_0_init;
    end
    else begin
      ram_wr_0 <= 1'b0;
      ram_addr_0 <= {6{1'b0}};
      ram_data_0 <= {3{1'b0}};
    end
  end
  //-------------------------------------------------
  // Multiplexor de la lectura de RAM (común a todos los fantasmas)
  //-------------------------------------------------
  always @(current_state, ram_addr_2_f1, ram_addr_2_f2, ram_addr_2_f3, ram_data_2) begin
    if(current_state == fantasma1_st) begin
      ram_addr_2 <= ram_addr_2_f1;
      ram_data_2_f1 <= ram_data_2;
      ram_data_2_f2 <= {3{1'b0}};
      ram_data_2_f3 <= {3{1'b0}};
    end
    else if(current_state == fantasma2_st) begin
      ram_addr_2 <= ram_addr_2_f2;
      ram_data_2_f2 <= ram_data_2;
      ram_data_2_f1 <= {3{1'b0}};
      ram_data_2_f3 <= {3{1'b0}};
    end
    else if(current_state == fantasma3_st) begin
      //
      ram_addr_2 <= ram_addr_2_f3;
      ram_data_2_f3 <= ram_data_2;
      ram_data_2_f1 <= {3{1'b0}};
      ram_data_2_f2 <= {3{1'b0}};
    end
    else begin
      ram_addr_2 <= {6{1'b0}};
      ram_data_2_f3 <= {3{1'b0}};
      ram_data_2_f2 <= {3{1'b0}};
      ram_data_2_f1 <= {3{1'b0}};
    end
  end
  //-------------------------------------------------
  // Proceso de actualizacion del estado
  //-------------------------------------------------
  always @(posedge clk_50MHz, posedge rst) begin
    if(rst == 1'b1) begin
      current_state <= s0;
    end else begin
      current_state <= next_state;
    end
  end
endmodule

`ifdef PRJ1_FPGA_IMPL
	// the board does not have enough GPIO, so we implement a 4-bit ALU
    `define DATA_WIDTH 4
`else
    `define DATA_WIDTH 32
`endif
module alu(
	input [`DATA_WIDTH - 1:0] A,
	input [`DATA_WIDTH - 1:0] B,
	input [2:0] ALUop,
	output Overflow,
	output CarryOut,
	output Zero,
	output reg [`DATA_WIDTH - 1:0] Result
);
	// TODO: insert your code
	wire OF, CF;
    wire [`DATA_WIDTH - 1:0] B_OP, Result_AND, Result_OR, Result_PLUS;
    always@(*)
    begin
       case(ALUop)
       3'b000: Result<=Result_AND;
       3'b001: Result<=Result_OR;
       3'b010, 3'b110: Result<=Result_PLUS;
       3'b111: Result<=OF;
       default: Result<=`DATA_WIDTH'b0;
       endcase
    end
    assign Result_AND=A&B;
    assign Result_OR=A|B;
    assign B_OP=B^{`DATA_WIDTH{ALUop[2]}};
    assign {CF, OF, Result_PLUS}={A[`DATA_WIDTH-1], A}+{B_OP[`DATA_WIDTH-1], B_OP}+ALUop[2];
    assign Overflow=OF^Result_PLUS[`DATA_WIDTH-1];
    assign CarryOut=CF^ALUop[2];
    assign Zero=~|Result_PLUS;
endmodule

