module fx2_interface(
input wire clk_in,
input wire reset_in,
output reg reset_out,
output reg fx2FifoSel_out,
inout wire [7:0] fx2Data_io,
output wire fx2Read_out,
input wire fx2GotData_in,
output wire fx2Write_out,
input wire fx2GotRoom_in,
output reg fx2PktEnd_out,
output wire [6:0] chanAddr_out,
output wire [7:0] h2fData_out,
output reg h2fValid_out,
input wire h2fReady_in,
input wire [7:0] f2hData_in,
input wire f2hValid_in,
output reg f2hReady_out
);
// 48MHz clock from FX2LP
// synchronous active-high reset input
// synchronous active-high reset output
// FX2LP interface ---------------------------------------------------------------------------
// select FIFO: '0' for EP2OUT, '1' for EP6IN
// 8-bit data to/from FX2LP
// When EP2OUT selected:
// asserted (active-low) when reading from FX2LP
// asserted (active-high) when FX2LP has data for us
// When EP6IN selected:
// asserted (active-low) when writing to FX2LP
// asserted (active-high) when FX2LP has room for more data from us
// asserted (active-low) when a host read needs to be committed early
// Channel read/write interface --------------------------------------------------------------
// the selected channel (0-127)
// Host >> FPGA pipe:
// data lines used when the host writes to a channel
// '1' means "on the next clock rising edge, please accept the data on h2fData_out"
// channel logic can drive this low to say "I'm not ready for more data yet"
// Host << FPGA pipe:
// data lines used when the host reads from a channel
// channel logic can drive this low to say "I don't have data ready for you"
// '1' means "on the next clock rising edge, put your next byte of data on f2hData_in"
// The read/write nomenclature here refers to the FPGA reading and writing the FX2LP FIFOs, and is therefore
// of the opposite sense to the host's read and write. So host reads are fulfilled in the S_WRITE state, and
// vice-versa. Apologies for the confusion.
parameter [3:0]
  S_RESET = 0,
  S_IDLE = 1,
  S_GET_COUNT0 = 2,
  S_GET_COUNT1 = 3,
  S_BEGIN_WRITE = 4,
  S_WRITE = 5,
  S_END_WRITE_ALIGNED = 6,
  S_END_WRITE_NONALIGNED = 7,
  S_READ = 8;
parameter FIFO_READ = 2'b10;  // assert fx2Read_out (active-low)
parameter FIFO_WRITE = 2'b01;  // assert fx2Write_out (active-low)
parameter FIFO_NOP = 2'b11;  // assert nothing
parameter OUT_FIFO = 1'b0;  // EP2OUT
parameter IN_FIFO = 1'b1;  // EP6IN
reg [3:0] state = S_RESET; reg [3:0] state_next = S_RESET;
reg [1:0] fifoOp = 2'bZZ;
reg [16:0] count = 1'b0; reg [16:0] count_next = 1'b0;  // read/write count
reg [6:0] chanAddr = 1'b0; reg [6:0] chanAddr_next = 1'b0;  // channel being accessed (0-127)
reg isWrite = 1'b0; reg isWrite_next = 1'b0;  // is this FX2LP FIFO access a write or a read?
reg isAligned = 1'b0; reg isAligned_next = 1'b0;  // is this FX2LP FIFO write block-aligned?
reg [7:0] dataOut;  // data to be driven on fx2Data_io
reg driveBus = 1'b0;  // whether or not to drive fx2Data_io
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_RESET;
      count <= {17{1'b0}};
      chanAddr <= {7{1'b0}};
      isWrite <= 1'b0;
      isAligned <= 1'b0;
    end
    else begin
      state <= state_next;
      count <= count_next;
      chanAddr <= chanAddr_next;
      isWrite <= isWrite_next;
      isAligned <= isAligned_next;
    end
  end
  // Next state logic
  always @(state, fx2Data_io, fx2GotData_in, fx2GotRoom_in, count, isAligned, isWrite, chanAddr, f2hData_in, f2hValid_in, h2fReady_in) begin
    state_next <= state;
    count_next <= count;
    chanAddr_next <= chanAddr;
    isWrite_next <= isWrite;
    // is the FPGA writing to the FX2LP?
    isAligned_next <= isAligned;
    // does this FIFO write end on a block (512-byte) boundary?
    dataOut <= {8{1'b0}};
    driveBus <= 1'b0;
    // don't drive fx2Data_io by default
    fifoOp <= FIFO_READ;
    // read the FX2LP FIFO by default
    fx2PktEnd_out <= 1'b1;
    // inactive: FPGA does not commit a short packet.
    f2hReady_out <= 1'b0;
    h2fValid_out <= 1'b0;
    reset_out <= 1'b0;
    case(state)
    S_GET_COUNT0 : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The count high word high byte will be available on the next clock edge.
        count_next[15:8] <= fx2Data_io;
        state_next <= S_GET_COUNT1;
      end
    end
    S_GET_COUNT1 : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The count high word low byte will be available on the next clock edge.
        count_next[7:0] <= fx2Data_io;
        if((count[15:8] == 8'h00 && fx2Data_io == 8'h00)) begin
          count_next[16] <= 1'b1;
        end
        else begin
          count_next[16] <= 1'b0;
        end
        if((isWrite == 1'b1)) begin
          state_next <= S_BEGIN_WRITE;
        end
        else begin
          state_next <= S_READ;
        end
      end
    end
    S_BEGIN_WRITE : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      if((count[8:0] == 9'b000000000)) begin
        isAligned_next <= 1'b1;
      end
      else begin
        isAligned_next <= 1'b0;
      end
      state_next <= S_WRITE;
    end
    S_WRITE : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      if((fx2GotRoom_in == 1'b1)) begin
        f2hReady_out <= 1'b1;
      end
      if((fx2GotRoom_in == 1'b1 && f2hValid_in == 1'b1)) begin
        fifoOp <= FIFO_WRITE;
        dataOut <= f2hData_in;
        driveBus <= 1'b1;
        count_next <= count - 1;
        if((count == 1)) begin
          if((isAligned == 1'b1)) begin
            state_next <= S_END_WRITE_ALIGNED;
            // don't assert fx2PktEnd
          end
          else begin
            state_next <= S_END_WRITE_NONALIGNED;
            // assert fx2PktEnd to commit small packet
          end
        end
      end
      else begin
        fifoOp <= FIFO_NOP;
      end
    end
    S_END_WRITE_ALIGNED : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      state_next <= S_IDLE;
    end
    S_END_WRITE_NONALIGNED : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      fx2PktEnd_out <= 1'b0;
      // Active: FPGA commits the packet early.
      state_next <= S_IDLE;
    end
    S_READ : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1 && h2fReady_in == 1'b1)) begin
        // A data byte will be available on the next clock edge
        h2fValid_out <= 1'b1;
        count_next <= count - 1;
        if((count == 1)) begin
          state_next <= S_IDLE;
        end
      end
      else begin
        fifoOp <= FIFO_NOP;
      end
      // S_RESET - tri-state everything
    end
    S_RESET : begin
      reset_out <= 1'b1;
      driveBus <= 1'b0;
      fifoOp <= 2'bZZ;
      fx2FifoSel_out <= 1'bZ;
      fx2PktEnd_out <= 1'bZ;
      if((fx2GotData_in == 1'b0)) begin
        state_next <= S_IDLE;
      end
      // S_IDLE and others
    end
    default : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The read/write flag and a seven-bit channel address will be available on the
        // next clock edge.
        chanAddr_next <= fx2Data_io[6:0];
        isWrite_next <= fx2Data_io[7];
        state_next <= S_GET_COUNT0;
      end
    end
    endcase
  end
  // Drive stateless signals
  assign fx2Read_out = fifoOp[0];
  assign fx2Write_out = fifoOp[1];
  assign chanAddr_out = chanAddr;
  assign h2fData_out = fx2Data_io;
  assign fx2Data_io = driveBus == 1'b1 ? dataOut : {8{1'bZ}};
endmodule

