input wire kbdClk,
input wire kbdData,
output reg kbdClkF,
output reg kbdDataF
);
parameter FILTER_WIDTH = 4;
reg [FILTER_WIDTH - 1:0] kbd_clkf_reg = 1'b1;
wire [FILTER_WIDTH - 1:0] kbd_Dataf_reg = 1'b1;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      kbd_clkf_reg <= {((FILTER_WIDTH - 1)-(0)+1){1'b1}};
      kbdClkF <= 1'b1;
    end else begin
      kbd_clkf_reg <= {kbdClk,kbd_clkf_reg[FILTER_WIDTH - 1:1]};
      //clock
      if((kbd_clkf_reg == 4'hF)) begin
        kbdClkF <= 1'b1;
