  end
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      kbd_dataf_reg <= {1{1'b1}};
      kbdDataF <= 1'b1;
    end else begin
      kbd_dataf_reg <= {kbdData,kbd_dataf_reg[FILTER_WIDTH - 1:1]};
      //data
      if((kbd_dataf_reg == 4'hF)) begin
        kbdDataF <= 1'b1;
      end
      else if((kbd_dataf_reg == 4'h0)) begin
        kbdDataF <= 1'b0;
      end
