module ripple_carry_adder(
input wire [2:0] a_in,
input wire [2:0] b_in,
output wire [3:0] s_out
);
//-----------------------------------------------------------------------------
// Architecture called 'gate' is already defined. Just fill it.
// Architecture defines an implementation for an entity
// TODO: Add your internal signal declarations here
wire carry_ha;
wire carry_fa;
wire C; wire D; wire E; wire F; wire G; wire H;
  // gate
  // Half adder.
  assign s_out[0] = a_in[0] ^ b_in[0];
  assign carry_ha = a_in[0] & b_in[0];
  // Full adder 1.
  assign C = a_in[1] ^ b_in[1];
  assign D = carry_ha & C;
  assign E = a_in[1] & b_in[1];
  assign s_out[1] = carry_ha ^ C;
  assign carry_fa = D | E;
  // Full adder 2.  
  assign F = a_in[2] ^ b_in[2];
  assign G = carry_fa & F;
  assign H = a_in[2] & b_in[2];
  assign s_out[2] = carry_fa ^ F;
  assign s_out[3] = G | H;
endmodule

