module Mealy10010 (
    input clk, rst, j, output w
);
reg [3:0] ns, ps;
parameter [3:0] A = 3'd0, B = 3'd1, C = 3'd2, D = 3'd3, E = 3'd4;
always @(ps, j) begin
    ns = A;
    case(ps)
        A: ns = j ? B : A;
        B: ns = j ? B : C;
        C: ns = j ? B : D;
        D: ns = j ? E : A;
        E: ns = j ? B : A;
    endcase
end
assign w = (ps == E) ? ~j : 1'b0;
always @(posedge clk, posedge rst) begin
    if(rst)
        ps <= 0;
    else
        ps <= ns;
end
endmodule

