module reset_tree #(
  parameter DELAY0 = 10,
  parameter DELAY1 = 10,
  parameter DELAY2 = 10)
(
  input clk,
  input rst0,
  input rst1,
  input rst2,
  output reg delay_rst0,
  output reg delay_rst1,
  output reg delay_rst2,
  output [3:0] stage
);
  reg [31:0] rst_cnt = 32'b0;
  reg [3:0]  wd_rst_cnt = 4'b0;
  reg        wd_rst;
  reg [3:0]  rst_stage;
  always @ (posedge clk) begin
    if (&wd_rst_cnt == 0) begin
      wd_rst_cnt <= wd_rst_cnt + 1;
      wd_rst <= 1'b1;
      end
    else
      wd_rst <= 1'b0;
    end
  always @ (posedge clk) begin
  if (wd_rst) begin
    rst_stage <= 4'b0001;
    delay_rst0 <= 1'b1;
    delay_rst1 <= 1'b1;
    delay_rst2 <= 1'b1;
    rst_cnt <= 32'b0;
    end
  else begin
    case (rst_stage)
      4'b0001 : begin
        if (!rst0) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst0 <= 1'b1;
          delay_rst1 <= 1'b1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY0) begin
            delay_rst0 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b0010;
            end
          end
        end
      4'b0010 : begin
        if (!rst1) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst1 <= 1'b1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY1) begin
            delay_rst1 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b0100;
            end
          end
        end
      4'b0100 : begin
        if (!rst2) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY2) begin
            delay_rst2 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b1000;
            end
          end
        end
      4'b1000 : begin
        delay_rst0 <= 1'b0;
        delay_rst1 <= 1'b0;
        delay_rst2 <= 1'b0;
        end
      default : rst_stage <= 4'b0001;
      endcase
    end
  end
  assign stage = rst_stage;
endmodule

module vga_laplacian_fusion(
input wire clk_25,
input wire [23:0] rgb_blur_0,
input wire [23:0] rgb_pass_0,
input wire [23:0] rgb_blur_1,
input wire [23:0] rgb_pass_1,
output reg [23:0] rgb_out
);
  always @(posedge clk_25) begin : P1
    reg [31:0] r_0, g_0, b_0, r_1, g_1, b_1;
    reg [31:0] r_diff_0, g_diff_0, b_diff_0, r_diff_1, g_diff_1, b_diff_1;
    r_0 = rgb_pass_0[23:16];
    g_0 = rgb_pass_0[15:8];
    b_0 = rgb_pass_0[7:0];
    r_1 = rgb_pass_1[23:16];
    g_1 = rgb_pass_1[15:8];
    b_1 = rgb_pass_1[7:0];
    r_diff_0 = r_0 - (rgb_blur_0[23:16]);
    g_diff_0 = g_0 - (rgb_blur_0[15:8]);
    b_diff_0 = b_0 - (rgb_blur_0[7:0]);
    r_diff_1 = r_1 - (rgb_blur_1[23:16]);
    g_diff_1 = g_1 - (rgb_blur_1[15:8]);
    b_diff_1 = b_1 - (rgb_blur_1[7:0]);
    rgb_out[23:16] <= r_0 * (r_diff_0 / (r_diff_0 + r_diff_1)) + r_1 * (r_diff_1 / (r_diff_0 + r_diff_1));
    rgb_out[15:8] <= g_0 * (g_diff_0 / (g_diff_0 + g_diff_1)) + g_1 * (g_diff_1 / (g_diff_0 + g_diff_1));
    rgb_out[7:0] <= b_0 * (b_diff_0 / (b_diff_0 + b_diff_1)) + b_1 * (b_diff_1 / (b_diff_0 + b_diff_1));
  end
endmodule

