module timer #(parameter BITS = 4)
(
    input clk,
    input reset,
    input enable,
    input [BITS - 1:0] FINAL_VALUE,
    output done
    );
    reg [BITS - 1:0] Q_reg, Q_next;
    always @(posedge clk, posedge reset)
    begin
        if (reset)
            Q_reg <= 'b0;
        else if(enable)
            Q_reg <= Q_next;
        else
            Q_reg <= Q_reg;
    end
    always @(*)
        Q_next = done? 'b0: Q_reg + 1;
    assign done = Q_reg == FINAL_VALUE;
endmodule

