module baudGen(
input wire clr,
input wire clk,
input wire [11:0] baudFreq,
input wire [15:0] baudLimit,
output reg ce16
);
// global reset input
// global clock input
// baudFreq = 16 * baudRate / gcd(clkFreq, 16 * baudRate)
// baud rate setting registers - see header description
// baudLimit = clkFreq / gcd(clkFreq, 16 * baudRate) - baudFreq
// baud rate setting registers - see header description
// baud rate multiplyed by 16
reg [15:0] counter;
  // baud divider counter
  // clock divider output
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      counter <= {16{1'b0}};
      ce16 <= 1'b0;
    end else begin
      if((counter >= baudLimit)) begin
        counter <= counter - baudLimit;
        ce16 <= 1'b1;
      end
      else begin
        counter <= counter + baudFreq;
        ce16 <= 1'b0;
      end
    end
  end
endmodule

module PWM (clock, reset, enable, pwm, counter);
	input clock, reset, enable;
	output pwm;
	output [4:0]counter;
	reg pwm;
	reg [4:0]counter;
//	reg [31:0]counter;
	always@(posedge clock or posedge reset)
	begin
		if (reset)
		begin
			pwm <= 0;
			counter <= 0;
		end
		else
		begin
			if (enable)
			begin
				if (counter < 2) // counter < 20000
				begin
					pwm <= 1;
					counter <= counter + 1;
				end
				else
				begin
					if (counter < 19) // counter < 200000
					begin
						pwm <= 0;
						counter <= counter + 1;
					end
					else
					begin
						counter <= 0;
					end
				end
			end
			else
			begin
				pwm <= 0;
				counter <= 0;
			end
		end
	end
endmodule

module mod10(
    output wire [3:0]   ones, 
    output wire       tc, zero,
    input wire        clearn, loadn, clock, en,
    input wire  [3:0] data); 
    reg [3:0] counter; 
    always @(posedge clock, negedge clearn)
        begin
          if (clearn == 1'b0)
              counter <= 0;
          else
            if (en == 1'b0)
              begin
                if (loadn == 1'b0)
                  counter <= data;
              end
            else 
              begin
                if (counter == 0)
                  counter <= 9;
                else
                  counter <= counter - 1;
              end 
        end
  assign tc = ((counter == 0) && (en == 1'b1)) ? 1'b1 : 1'b0;
  assign zero = (counter == 0) ? 1'b1 : 1'b0;
  assign ones = counter;
endmodule

// 4-bits synchronous up counter
// active high, synchronous reset
// active high enable
module counter(clock, reset, enable, counter_out);
  input wire clock;
  input wire reset;
  input wire enable;
  output reg [3:0] counter_out;
  always @ (posedge clock)
  begin: COUNTER
    if(reset == 1'b1) begin
      counter_out <= 4'b0000;
    end
    else if(enable == 1'b1) begin
      counter_out <= counter_out + 1;
    end
  end
endmodule

