module DEBOUNCER(
input wire CLK,
input wire RST,
input wire DIN,
output wire DOUT
);
// Clock
// High active asynchronous reset
// Data input
// Debounced data output
reg [3:0] data_shreg;
reg data_deb_reg;
  assign DOUT = data_deb_reg;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data_shreg <= {4{1'b0}};
      data_deb_reg <= 1'b0;
    end else begin
      data_shreg <= {data_shreg[2:0],DIN};
      data_deb_reg <= data_shreg[0] & data_shreg[1] & data_shreg[2] & data_shreg[3];
    end
  end
endmodule

