module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
    );
    wire [2:0]r;
    xor x1(sum,a,b,cin);
    and a1(r[0],a,b);
    and a2(r[1],b,cin);
    and a3(r[2],cin,a);
    or o1(cout,r[0],r[1],r[2]);
endmodule

module ALU_Toplevel(
input wire [15:0] RA,
input wire [15:0] RB,
input wire [3:0] OP,
input wire CLK,
output reg [15:0] ALU_OUT,
output reg [3:0] SREG,
output wire [15:0] LDST_DAT,
output wire [15:0] LDST_ADR
);
wire [15:0] ARITH = 1'b0;
wire [3:0] SREG_AR = 1'b0;
wire [15:0] LOGIC = 1'b0;
wire [3:0] SREG_LG = 1'b0;
wire [15:0] SHIFT = 1'b0;
wire [3:0] SREG_SH = 1'b0;
wire [15:0] LD_MEM = 1'b0;
wire [15:0] WORD_OUT = 1'b0;
wire [7:0] LDST_ADR_8 = 1'b0;
  assign LDST_ADR = {8'h00,LDST_ADR_8};
  arith_unit arith_unit(
      .RA(RA),
    .RB(RB),
    .OP(OP[2:0]),
    .AR_OUT(ARITH),
    .SREG_OUT(SREG_AR));
  logical_unit logical_unit(
      .RA(RA),
    .RB(RB),
    .OP(OP[2:0]),
    .LOG_OUT(LOGIC),
    .SREG_OUT(SREG_LG));
  shift_unit shift_unit(
      .RA(RA),
    .SHIFT(RB[7:0]),
    .OP(OP[3]),
    .SHIFT_OUT(SHIFT),
    .SREG_OUT(SREG_SH));
  word_unit word_unit(
      .DATAIN(RA),
    .IMMAddr(RB[7:0]),
    .CLK(CLK),
    .OP(OP),
    .RESULT(WORD_OUT),
    .DST_ADR(LDST_ADR_8),
    .STORE_DATA(LDST_DAT));
  //	ALU_OUT <= RA;
  always @(*) begin
    case(OP)
      4'b0000 : ALU_OUT <= ARITH;
  // ADD (ARITHMETIC)
      4'b0001 : ALU_OUT <= ARITH;
  // SUB (ARITHMETIC)
      4'b0010 : ALU_OUT <= LOGIC;
  // AND (LOGICAL)
      4'b0011 : ALU_OUT <= LOGIC;
  // OR  (LOGICAL)
      4'b0100 : ALU_OUT <= LOGIC;
  // MOV (LOGICAL)
      4'b0101 : ALU_OUT <= ARITH;
  // ADDI (ARITHMETIC)
      4'b0110 : ALU_OUT <= LOGIC;
  //, -- ANDI (LOGICAL)
      4'b0111 : ALU_OUT <= SHIFT;
  // SL (SHIFT)
      4'b1000 : ALU_OUT <= SHIFT;
  //, -- SR (SHIFT)
      4'b1001 : ALU_OUT <= WORD_OUT;
  // LW (WORD)
      4'b1010 : ALU_OUT <= RA;
  // SW (WORD)
      default : ALU_OUT <= 16'h0000;
    endcase
  end
  always @(*) begin
    case(OP)
      4'b0000 : SREG <= SREG_AR;
  // ADD (ARITHMETIC)
      4'b0001 : SREG <= SREG_AR;
  // SUB (ARITHMETIC)
      4'b0010 : SREG <= SREG_LG;
  // AND (LOGICAL)
      4'b0011 : SREG <= SREG_LG;
  // OR  (LOGICAL)
      4'b0100 : SREG <= SREG_LG;
  // MOV (LOGICAL)
      4'b0101 : SREG <= SREG_AR;
  // ADDI (ARITHMETIC)
      4'b0110 : SREG <= SREG_LG;
  //, -- ANDI (LOGICAL)
      4'b0111 : SREG <= SREG_SH;
  // SL (SHIFT)
      4'b1000 : SREG <= SREG_SH;
  //, -- SR (SHIFT)
      default : SREG <= 4'h0;
    endcase
  end
endmodule
